//! The `Injectable` trait (generated by `#[injectable]`, `#[controller]` and `#[module]`)
//! and the resolution context handed to constructors and factories.

use std::sync::Arc;

use futures::FutureExt;
use futures::future::BoxFuture;

use super::container::{Container, ModuleId};
use super::error::DiError;
use super::module_ref::ModuleRef;
use super::provider::{Instance, Scope, downcast};
use super::token::Token;

type LifecycleHook<T> = fn(Arc<T>) -> BoxFuture<'static, crate::Result<()>>;
type ShutdownHook<T> = fn(Arc<T>, Option<String>) -> BoxFuture<'static, crate::Result<()>>;
type HandlersFn<T> = fn(Arc<T>) -> Vec<crate::discovery::DiscoveredHandler>;
type GatewayFn<T> = fn(Arc<T>) -> crate::discovery::GatewayInfo;

/// Typed lifecycle hooks detected at compile time by the `#[injectable]` family of macros.
pub struct Hooks<T> {
    pub on_module_init: Option<LifecycleHook<T>>,
    pub on_application_bootstrap: Option<LifecycleHook<T>>,
    pub on_module_destroy: Option<LifecycleHook<T>>,
    pub before_application_shutdown: Option<ShutdownHook<T>>,
    pub on_application_shutdown: Option<ShutdownHook<T>>,
    pub handlers: Option<HandlersFn<T>>,
    pub gateway: Option<GatewayFn<T>>,
}

impl<T> Default for Hooks<T> {
    fn default() -> Self {
        Hooks {
            on_module_init: None,
            on_application_bootstrap: None,
            on_module_destroy: None,
            before_application_shutdown: None,
            on_application_shutdown: None,
            handlers: None,
            gateway: None,
        }
    }
}

/// A class that can be instantiated by the DI container. Equivalent to `@Injectable()`.
///
/// You normally never implement this by hand: use `#[injectable]`.
pub trait Injectable: Sized + Send + Sync + 'static {
    fn construct(ctx: ResolveCtx) -> BoxFuture<'static, Result<Self, DiError>>;

    fn hooks() -> Hooks<Self> {
        Hooks::default()
    }

    fn scope() -> Scope {
        Scope::Default
    }
}

/// Context available while a provider is being constructed. Inside a factory
/// provider it plays the role of the `inject: [...]` array of a factory provider.
#[derive(Clone)]
pub struct ResolveCtx {
    pub(crate) container: Arc<Container>,
    pub(crate) module: ModuleId,
    pub(crate) requester: Arc<str>,
    pub(crate) deps: &'static [&'static str],
    pub(crate) path: Arc<Vec<(ModuleId, Token)>>,
}

impl ResolveCtx {
    pub(crate) fn for_module(container: Arc<Container>, module: ModuleId) -> Self {
        ResolveCtx { container, module, requester: Arc::from(""), deps: &[], path: Arc::new(Vec::new()) }
    }

    /// Declares the dependency list of the class under construction (used for error messages).
    pub fn with_dependencies(mut self, requester: &str, deps: &'static [&'static str]) -> Self {
        self.requester = Arc::from(requester);
        self.deps = deps;
        self
    }

    /// Resolve a class provider: `ctx.get::<CatsService>().await?`.
    pub async fn get<T: ?Sized + Send + Sync + 'static>(&self) -> Result<Arc<T>, DiError> {
        self.get_token(Token::of::<T>()).await
    }

    /// Resolve a provider by token: `ctx.get_token::<Config>("CONFIG_OPTIONS").await?`.
    pub async fn get_token<T: ?Sized + Send + Sync + 'static>(&self, token: impl Into<Token>) -> Result<Arc<T>, DiError> {
        let token = token.into();
        let instance = self.resolve_instance(token.clone()).await?;
        downcast::<T>(&instance)
            .ok_or_else(|| DiError::TypeMismatch { token: token.display_name(), expected: std::any::type_name::<T>().to_string() })
    }

    /// Resolve an optional dependency (`@Optional()`).
    pub async fn get_optional<T: ?Sized + Send + Sync + 'static>(&self, token: impl Into<Token>) -> Result<Option<Arc<T>>, DiError> {
        let token = token.into();
        if self.container.lookup(self.module, &token).is_none() {
            return Ok(None);
        }
        self.get_token::<T>(token).await.map(Some)
    }

    pub(crate) async fn resolve_instance(&self, token: Token) -> Result<Instance, DiError> {
        self.container.clone().resolve(self.module, token, self.path.clone()).await
    }

    /// Used by generated constructors: resolves the dependency at `index`, producing
    /// a descriptive error message if it cannot be found.
    pub async fn resolve_dependency<T: ?Sized + Send + Sync + 'static>(&self, token: Token, index: usize) -> Result<Arc<T>, DiError> {
        if self.container.lookup(self.module, &token).is_none() {
            let deps = self
                .deps
                .iter()
                .enumerate()
                .map(|(i, d)| if i == index { "?".to_string() } else { d.to_string() })
                .collect::<Vec<_>>()
                .join(", ");
            return Err(DiError::UnknownDependencies {
                requester: self.requester.to_string(),
                deps,
                token: token.display_name(),
                index,
                module: self.container.module_name(self.module),
            });
        }
        self.get_token::<T>(token).await
    }

    /// Resolve `T` from the module if registered as a provider, otherwise instantiate
    /// it (and cache it) in the context of the current module. Used for guards,
    /// interceptors, pipes, filters and middleware referenced by type.
    pub async fn get_or_construct<T: Injectable>(&self) -> Result<Arc<T>, DiError> {
        let token = Token::of::<T>();
        if self.container.lookup(self.module, &token).is_some() {
            return self.get::<T>().await;
        }
        self.container.clone().construct_injectable::<T>(self.module).await
    }

    /// A [`ModuleRef`] pointing at the module currently being resolved.
    pub fn module_ref(&self) -> ModuleRef {
        ModuleRef { container: self.container.clone(), module: self.module }
    }

    /// Name of the module currently being resolved.
    pub fn module_name(&self) -> String {
        self.container.module_name(self.module)
    }
}

/// Types that can appear as fields of an `#[injectable]` struct and be resolved
/// from the container (`Arc<T>`, `Option<Arc<T>>`, `ModuleRef`).
pub trait InjectField: Sized + Send + 'static {
    fn inject(ctx: ResolveCtx, token: Option<Token>, index: usize) -> BoxFuture<'static, Result<Self, DiError>>;
}

impl<T: ?Sized + Send + Sync + 'static> InjectField for Arc<T> {
    fn inject(ctx: ResolveCtx, token: Option<Token>, index: usize) -> BoxFuture<'static, Result<Self, DiError>> {
        async move {
            let token = token.unwrap_or_else(Token::of::<T>);
            ctx.resolve_dependency::<T>(token, index).await
        }
        .boxed()
    }
}

impl<T: ?Sized + Send + Sync + 'static> InjectField for Option<Arc<T>> {
    fn inject(ctx: ResolveCtx, token: Option<Token>, _index: usize) -> BoxFuture<'static, Result<Self, DiError>> {
        async move {
            let token = token.unwrap_or_else(Token::of::<T>);
            ctx.get_optional::<T>(token).await
        }
        .boxed()
    }
}

impl InjectField for ModuleRef {
    fn inject(ctx: ResolveCtx, _token: Option<Token>, _index: usize) -> BoxFuture<'static, Result<Self, DiError>> {
        async move { Ok(ctx.module_ref()) }.boxed()
    }
}
